#!/usr/bin/env node
// R316 (2026-10-02) — writes automation/r316.bat, the action of the "TRAIDS R316 1354" / "TRAIDS R316 1357" tasks.
// Written from this node FILE (never bash / node -e / PowerShell): explicit CRLF, every backslash from String.fromCharCode(92) — a
// 2026-10-02 .bat lost its backslash when it was written through a shell. Overwrites only its OWN earlier output (recognised by the
// "Generated by docs\r316\build-bat.cjs" line); refuses to overwrite any other file at that path.
//
// ONE LOG PER FIRE (2026-10-02 review, reproduced with two real cmd.exe processes): cmd opens a `>>` target without write sharing, so
// while the primary (13:54 task) still holds `>> r316.log`, the backup (13:57 task) cannot open it, node never starts, cmd exits, and
// nothing reaches the log — the backup and its "lock held" alert vanish exactly when they are needed. Each task passes its fire tag
// (1354 / 1357) as %1; the .bat accepts only those two tags (anything else = "manual") and writes automation\r316-<tag>.log.
"use strict";
const fs = require("fs"), path = require("path");
const BS = String.fromCharCode(92), CRLF = String.fromCharCode(13, 10);
const REPO = path.resolve(__dirname, "..", ".."), OUT = path.join(REPO, "automation", "r316.bat");
const MARK = "REM Generated by docs" + BS + "r316" + BS + "build-bat.cjs";
const LOG = "\"%~dp0r316-%FIRE%.log\"";
const lines = [
  "@echo off",
  "REM TRAIDS R316 decision (2026-10-02, operator: \"run R313 forward\"). Run by the \"TRAIDS R316 1354\" task (13:54 MT = 15:54 ET on weekdays,",
  "REM local-time trigger, follows DST) and its backup \"TRAIDS R316 1357\" (15:57 ET), plus 10:54 / 10:57 MT on NYSE early-close dates.",
  "REM The runner refuses outside [close-6, close-1) ET on Alpaca's calendar, waits until close-5:00, decides ONCE a day from live Schwab",
  "REM quotes and sends DAY market orders to the Alpaca PAPER TV account (hard guard: no POST outside close-10..close-1 ET or to a",
  "REM non-paper host). The backup fire sends nothing already sent. Fills, official bars and the shadow are the close chain's (--after-close).",
  "REM The first argument is the fire tag from the task (1354 or 1357; anything else = manual). One log per fire, automation" + BS + "r316-TAG.log:",
  "REM cmd opens an append-redirect target without write sharing, so two fires on one log would keep the backup from starting while the primary runs.",
  MARK + "; never edit this file through PowerShell (encoding).",
  "cd /d \"%~dp0..\"",
  "set \"FIRE=manual\"",
  "if \"%~1\"==\"1354\" set \"FIRE=1354\"",
  "if \"%~1\"==\"1357\" set \"FIRE=1357\"",
  "echo [%date% %time%] r316 decide %FIRE% >> " + LOG,
  "node backend" + BS + "r316-ibs-forward.js --decide --live --by task%FIRE% >> " + LOG + " 2>&1",
];
const text = lines.join(CRLF) + CRLF;
// proofs on the output
const must = ["cd /d \"%~dp0..\"", "node backend" + BS + "r316-ibs-forward.js --decide --live --by task%FIRE%", ">> \"%~dp0r316-%FIRE%.log\" 2>&1",
  "if \"%~1\"==\"1354\" set \"FIRE=1354\"", "if \"%~1\"==\"1357\" set \"FIRE=1357\"", "set \"FIRE=manual\"", MARK];
for (const m of must) if (!text.includes(m)) throw new Error("missing in the .bat: " + m);
if (/r316\.log/.test(text)) throw new Error("the shared r316.log is back in the .bat");
for (const l of lines) if (/^REM /.test(l) && /[<>|&%^]/.test(l)) throw new Error("a cmd metacharacter in a REM line: " + l);
if (/[^\r]\n/.test(text)) throw new Error("a bare LF slipped in");
if (!Buffer.from(text, "latin1").includes(Buffer.from([0x5c, 0x72, 0x33, 0x31, 0x36]))) throw new Error("the backslash before r316 is missing");
if (/[^\x00-\x7f]/.test(text)) throw new Error("non-ASCII in the .bat");
if (fs.existsSync(OUT)) {
  const cur = fs.readFileSync(OUT, "latin1");
  if (cur === text) { console.log("automation/r316.bat already identical — unchanged"); process.exit(0); }
  if (!cur.includes(MARK)) throw new Error("automation/r316.bat exists, differs and is not this generator's output — refusing to overwrite");
  console.log("automation/r316.bat is this generator's earlier output — replacing it");
}
fs.writeFileSync(OUT, Buffer.from(text, "latin1"));
const back = fs.readFileSync(OUT, "latin1"); if (back !== text) throw new Error("read-back differs from what was written");
console.log(`wrote ${OUT} (${text.length} bytes, ${lines.length} lines, CRLF, ASCII; read back identical)`);
